package com.metabuild.modules.admin.company.controller;
import com.metabuild.admin.api.security.RequiresPermissions;import com.metabuild.modules.admin.auth.api.CurrentAuthorizationProvider;import com.metabuild.modules.admin.company.application.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/company") public final class CompanyController {private final CompanyService service;private final CurrentAuthorizationProvider current;public CompanyController(CompanyService service,CurrentAuthorizationProvider current){this.service=service;this.current=current;}@GetMapping @RequiresPermissions(codes={"sys:org:view"}) public CompanyView get(){return service.get();}@PutMapping @RequiresPermissions(codes={"sys:org:edit"}) public CompanyView update(@RequestBody CompanyUpdate value){return service.update(current.current().userId(),value);}}
